SELECT COUNT(*) AS rent_listings_count
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT MAX(sale_price) AS highest_price
FROM nlq.listings
WHERE category = 'textbooks' AND sale_price IS NOT NULL;

SELECT COUNT(*) AS reviews_with_comment
FROM nlq.reviews
WHERE comment IS NOT NULL AND trim(comment) <> '';

select count(*) as conversations_without_seller_reply
from nlq.conversations
where first_seller_reply_at is null;

SELECT round(avg(extract(epoch from resolved_at - filed_at) / 86400)::numeric, 2) AS avg_resolution_days
FROM nlq.reports
WHERE status = 'resolved' AND resolved_at IS NOT NULL;

SELECT COUNT(*) AS listings_without_photos
FROM nlq.listings_all
WHERE photo_count = 0;
